From 617cb5ea618feb04b63583eb83dc895a4daed64c Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 14:35:18 +0100
Subject: [PATCH] shell: ask about unsaved changes before configuring another
 widget

Opening the settings of a widget while another widget's settings window
had unapplied changes silently replaced that window and lost the changes.
Close the open window first so it can ask to apply or discard them.

BUG: 430564
---
 shell/desktopview.cpp | 4 ++++
 shell/panelview.cpp   | 4 ++++
 2 files changed, 8 insertions(+)

diff --git a/shell/desktopview.cpp b/shell/desktopview.cpp
index 09ed56a17e..9c10b4c042 100644
--- a/shell/desktopview.cpp
+++ b/shell/desktopview.cpp
@@ -452,6 +452,10 @@ void DesktopView::showConfigurationInterface(Plasma::Applet *applet)
 {
     if (m_configView) {
         if (m_configView->applet() != applet) {
+            if (m_configView->isVisible() && !m_configView->close()) {
+                m_configView->requestActivate();
+                return;
+            }
             m_configView->hide();
             m_configView->deleteLater();
         } else {
diff --git a/shell/panelview.cpp b/shell/panelview.cpp
index 5c0ac43e71..d8f8c9e298 100644
--- a/shell/panelview.cpp
+++ b/shell/panelview.cpp
@@ -933,6 +933,10 @@ void PanelView::showConfigurationInterface(Plasma::Applet *applet)
             m_appletConfigView->requestActivate();
             return;
         } else if (m_appletConfigView) {
+            if (m_appletConfigView->isVisible() && !m_appletConfigView->close()) {
+                m_appletConfigView->requestActivate();
+                return;
+            }
             m_appletConfigView->deleteLater(); // BUG 476968
         }
         m_appletConfigView = new PlasmaQuick::ConfigView(applet);
-- 
